#!/usr/bin/env python3
"""Regenerates firmware/src/app/wb/toys/rush_plan.h (see the note in it)."""
import os
out=['/* Snare Rush: when each hit of the roll falls, in 1000ths of a step, for each Length (1..4) and',
     ' * Speed-up (0..10): Playbox computed these in floating point (4 ** (accel / 10)); the table keeps',
     ' * them exact without a double on the device. Generated by ref/gen_rush.py. */',
     'static const uint16_t RU_PLAN[4][11][72] = {']
for span in range(1,5):
    out.append('    {')
    for accel in range(11):
        total=span*4000; ratio=4**(accel/10); hits=[]; t=0
        while t < total-100:
            hits.append(int(t)); t += 1000/ratio**(t/total)
        out.append('        {'+', '.join(str(v) for v in hits+[65535]*(72-len(hits)))+'},')
    out.append('    },')
out.append('};')
p=os.path.join(os.path.dirname(os.path.abspath(__file__)),'..','firmware','src','app','wb','toys','rush_plan.h')
open(p,'w').write('\n'.join(out)+'\n')
